/* @lc app=leetcode id=3281 lang=kotlin */ class Solution { fun ok(s: List<Int>, d: Int, x: Long): Boolean = s.drop(1).fold(s[0].toLong()) { cur, v -> if (cur < 0) -1L else maxOf(cur + x, v.toLong()).let { if (it > v.toLong() + d) -1L else it } } >= 0 fun maxPossibleScore(start: IntArray, d: Int): Int = start.sorted().let { s -> generateSequence(0L to 2_000_000_000L) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { m -> if (ok(s, d, m)) m to hi else lo to m - 1 } }.last().first.toInt() } }